D=Path(__file__).resolve().parent;spec=importlib.util.spec_from_file_location('r2_active_observer_source',D/'run.py');runner=importlib.util.module_from_spec(spec);spec.loader.exec_module(runner)
JS=r'''const vm=require('vm'),fs=require('fs'),ext=fs.readFileSync(0,'utf8');const receiver={},event={decision:'COMPONENT',plotCount:13,trackCount:13,certifiedCount:13,lowerBoundCertifiedCount:3,exactResidualCertifiedCount:10,reason:'LARGE_COMPONENT_REFINED_EXACT'},input={route:'OWN_SPY_GLOBAL',plotCount:13,gate:64,pairs:[{i:0,id:1,nis:2,truthCanary:'NEVER_COPY'}]},result={pairs:[{i:0,id:1,nis:2}],heldPlots:new Set(),heldTracks:new Set(),components:[{plots:Array(13).fill(0)}],active:true,stabilizationActive:true},traceMarker={};let tc=0,sc=0,st=null,sa=null;const ctx={window:{},simStepCounter:158,trackBTraceB(...args){tc++;return traceMarker;},trackBSelectB(...args){sc++;st=this;sa=args;return result;}};vm.runInNewContext(ext,ctx);ctx.window.__R2_BATTLE_TRACE__.install();const selected=ctx.trackBSelectB.call(receiver,input,'ARG'),traced=ctx.trackBTraceB(event);const snap=ctx.window.__R2_BATTLE_TRACE__.snapshot();const checks={selectorOnce:sc===1,selectorThis:st===receiver,selectorArgs:sa[0]===input&&sa[1]==='ARG',selectorReturnIdentity:selected===result,traceOnce:tc===1,traceReturnIdentity:traced===traceMarker,oneGraph:snap.graphs.length===1,nativeNisCopied:snap.graphs[0].pairs[0].nis===2,noUnknownTruthField:!JSON.stringify(snap.graphs).includes('NEVER_COPY'),originalInputUnchanged:input.pairs[0].truthCanary==='NEVER_COPY',faultZero:snap.faults.length===0,dropZero:snap.dropped===0};process.stdout.write(JSON.stringify({status:Object.values(checks).every(Boolean)?'PASS':'FAIL',checks,gameNativeCalls:0}));'''
def main():
 r=json.loads(subprocess.check_output(['node','-e',JS],input=runner.EXTENSION.encode()));r['schema']='AEGIS_R2_ACTIVE_OBSERVER_PURE_GUARD_1';r['extensionSha256']=hashlib.sha256(runner.EXTENSION.encode()).hexdigest();(D/'PURE_GUARD.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r));assert r['status']=='PASS'
